<script setup lang="ts">
import { ref } from 'vue'; import { RouterLink, useRoute, useRouter } from 'vue-router'; import { useAuthStore } from '@/stores/auth'; import { errorMessage } from '@/lib/api'
const auth = useAuthStore(); const router = useRouter(); const route = useRoute(); const mode = ref<'login'|'register'>('login'); const name = ref(''); const email = ref(''); const password = ref(''); const confirmation = ref(''); const error = ref(''); const loading = ref(false)
async function submit() { loading.value=true; error.value=''; try { if (mode.value==='login') await auth.login(email.value,password.value); else await auth.register(name.value,email.value,password.value,confirmation.value); router.push(String(route.query.redirect || '/')) } catch (cause:unknown) { error.value=errorMessage(cause,'Thông tin chưa hợp lệ.') } finally { loading.value=false } }
</script>
<template><section class="card form"><h1>{{ mode==='login' ? 'Đăng nhập' : 'Tạo tài khoản' }}</h1><p class="muted">Quản lý lịch đặt sân cầu lông của bạn.</p><form @submit.prevent="submit"><div v-if="mode==='register'" class="field"><label for="name">Họ tên</label><input id="name" name="name" v-model="name" autocomplete="name" required /></div><div class="field"><label for="email">Email</label><input id="email" name="email" v-model="email" type="email" autocomplete="email" required /></div><div class="field"><label for="password">Mật khẩu</label><input id="password" name="password" v-model="password" type="password" autocomplete="current-password" minlength="8" required /></div><div v-if="mode==='register'" class="field"><label for="password-confirmation">Nhập lại mật khẩu</label><input id="password-confirmation" name="password_confirmation" v-model="confirmation" type="password" autocomplete="new-password" minlength="8" required /></div><p v-if="error" class="error">{{ error }}</p><button class="btn" :disabled="loading">{{ mode==='login' ? 'Đăng nhập' : 'Đăng ký' }}</button></form><p v-if="mode==='login'" class="muted demo-request-note">Muốn trải nghiệm bản demo? Hãy inbox để được cấp tài khoản riêng.</p><RouterLink v-if="mode==='login'" to="/forgot-password" class="muted" style="display:inline-block;margin-top:16px">Quên mật khẩu?</RouterLink><p><button class="link-button" style="color:#0e6b50" @click="mode=mode==='login'?'register':'login'">{{ mode==='login' ? 'Chưa có tài khoản? Đăng ký' : 'Đã có tài khoản? Đăng nhập' }}</button></p></section></template>
